/**
 * Validate election-world-data.js and that election-v2 builds with it.
 *
 * Usage: npm run validate:election-world
 */

const path = require('path')

const world = require(path.join(__dirname, '../source/lib/election-world-data.js'))
const v2 = require(path.join(__dirname, '../source/lib/election-v2.js'))

world.validateWorldData(v2.STRATUM_IDS)

const districts = v2.buildDistricts()
const igs = v2.buildInterestGroups()

if (districts.length !== v2.DISTRICT_IDS.length) {
    console.error('validate-election-world: district count mismatch')
    process.exit(1)
}

for (const d of districts) {
    if (d.populations.length !== v2.STRATUM_IDS.length) {
        console.error(
            `validate-election-world: ${d.id} populations length `
            + `${d.populations.length} !== ${v2.STRATUM_IDS.length}`
        )
        process.exit(1)
    }
}

for (const ig of igs) {
    if (ig.membership.length !== v2.STRATUM_IDS.length) {
        console.error(
            `validate-election-world: ${ig.id} membership length `
            + `${ig.membership.length} !== ${v2.STRATUM_IDS.length}`
        )
        process.exit(1)
    }
}

console.log(
    'validate-election-world: OK —',
    v2.STRATUM_IDS.length,
    'strata,',
    districts.length,
    'districts,',
    igs.length,
    'interest groups'
)

