const world = require(path.join(__dirname, '../source/lib/election-world-data.js'))
const { STRATUM_IDS, initElectionV2 } = require(path.join(__dirname, '../source/lib/election-v2.js'))

world.validateWorldData(STRATUM_IDS)

const { state } = initElectionV2({ scenario: 'baseline' })
const districts = state.districts
const igs = state.interestGroups

if (districts.length !== 7) {
    console.error('validate-election-world: district count mismatch')
    process.exit(1)
}

for (const d of districts) {
    if (d.populations.length !== STRATUM_IDS.length) {
        console.error(
            `validate-election-world: ${d.id} populations length `
            + `${d.populations.length} !== ${STRATUM_IDS.length}`
        )
        process.exit(1)
    }
}

for (const ig of igs) {
    if (ig.membership.length !== STRATUM_IDS.length) {
        console.error(
            `validate-election-world: ${ig.id} membership length `
            + `${ig.membership.length} !== ${STRATUM_IDS.length}`
        )
        process.exit(1)
    }
}

console.log(
    'validate-election-world: OK —',
    STRATUM_IDS.length,
    'strata,',
    districts.length,
    'districts,',
    igs.length,
    'interest groups'
)

